def _query_expenses(db_path: str, submitter: str) -> list[dict[str, object]]:
    conn = _connect(db_path)
    try:
        conn.execute(_SCHEMA)
        rows = conn.execute(
            "SELECT id, submitter, purpose, amount_minor, status"
            " FROM expenses WHERE submitter = ? ORDER BY id ASC",
            (submitter,),
        ).fetchall()
    finally:
        conn.close()
    return [
        {
            "id": row[0],
            "submitter": row[1],
            "purpose": row[2],
            "amount_minor": row[3],
            "status": row[4],
        }
        for row in rows
    ]

